{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello आपको कौन सा product चाहिए?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "ನಂದು business ಗೆ ಒಂದು piece ಬೇಕು."
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "माफ़ कीजिए मैं समझ नहीं पाई।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "आप कृपया बता सकते हैं कि आपको कौन सा product चाहिए?"
    },
    {
      "i": 4,
      "speaker": "caller",
      "text": "Nandi brand का broom stick."
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "आपको Nandi brand की broom sticks जो आमतौर पर सफाई के काम आती है वही product चाहिए ना?"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "आपको कितने piece चाहिए होंगे?"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "एक ही।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "आपको material में क्या चाहिए जैसे coconut, coconut stick या कुछ और?"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "Coconut?"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "आपको weight में क्या चाहिए जैसे 400 grams, 300 grams या कुछ और?"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "कितना piece?"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "ठीक है आप अपनी city और state भी बता दीजिए please."
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "Bengaluru Devanagari."
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "आप Bengaluru Karnataka से बोल रहे हैं ना?"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "बैंगलोर करने।"
    },
    {
      "i": 20,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 21,
      "speaker": "caller",
      "text": "क्या आप अभी line पर हैं?"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "ठीक है आप अपना नाम भी बता दीजिए please."
    },
    {
      "i": 24,
      "speaker": "caller",
      "text": "लक्ष्मी हर्ष।"
    },
    {
      "i": 25,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 26,
      "speaker": "bot",
      "text": "लक्ष्मी हर्षा जी आपको मैं seller details WhatsApp से भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 27,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 28,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    }
  ]
}
